const items = $input.all();
const data = items[0]?.json;
if (!data) throw new Error('Keine Meteoblue-Daten');

const palette = {bg:'#0e1621',cardBg:'#1a2332',textPrimary:'#f5e6d3',textSecondary:'#d4e3f0',textTertiary:'#8f98a0',gold:'#FFB300',teal:'#36C3F2',blue:'#1e90ff',border:'#2a3f5f'};
const scoreColors = {0:{bg:'#ff6b6b',grad:'linear-gradient(135deg,#ff6b6b,#d32f2f)',label:'Keine Thermik',emoji:'🔴'},1:{bg:'#ff8a65',grad:'linear-gradient(135deg,#ff8a65,#e64a19)',label:'Sehr schwach',emoji:'🔴'},2:{bg:'#ffa726',grad:'linear-gradient(135deg,#ffa726,#f57c00)',label:'Schwach',emoji:'🟠'},3:{bg:'#FFB300',grad:'linear-gradient(135deg,#FFB300,#f57f17)',label:'Brauchbar',emoji:'🟡'},4:{bg:'#66bb6a',grad:'linear-gradient(135deg,#66bb6a,#43a047)',label:'Gut',emoji:'🟢'},5:{bg:'#36C3F2',grad:'linear-gradient(135deg,#36C3F2,#0288d1)',label:'Exzellent',emoji:'🟢'}};

function pick(o,...keys){for(const k of keys){if(o&&o[k]!=null)return o[k]}return null}
function mean(arr){const v=arr.filter(x=>Number.isFinite(x));return v.length?v.reduce((s,x)=>s+x,0)/v.length:null}
function round(v,d=1){return v==null?null:Math.round(v*10**d)/10**d}
function pct(v){return v==null?null:Math.round(v)}
function estimateTd(t,rh){return t==null||rh==null?null:t-(100-rh)/5}
function degToCompass(deg){if(deg==null)return'—';const dirs=['N','NE','E','SE','S','SW','W','NW'];const idx=Math.round(deg/45)%8;return dirs[idx];}

function parseSeries(j){
  const d1=j?.data_1h,b1h=j['basic-1h']||j.basic_1h,c1h=j['clouds-1h']||j.clouds_1h,a1h=j['air-1h']||j.air_1h;
  const time=d1?.time||b1h?.time||a1h?.time||c1h?.time;
  if(!time)throw new Error('Keine 1h Zeitreihe');
  return {time,temp:pick(d1,'temperature','temperature_2m')||pick(b1h||a1h,'temperature','temperature_2m','t_2m'),rh:pick(d1,'relative_humidity','relativehumidity_2m')||pick(b1h||a1h,'relative_humidity','relativehumidity_2m'),wind10:pick(d1,'windspeed','windspeed_10m')||pick(b1h||a1h,'windspeed','windspeed_10m'),winddir:pick(d1,'winddirection','winddirection_10m')||pick(b1h||a1h,'winddirection','winddirection_10m'),precip:pick(d1,'precipitation','precipitation_1h')||pick(b1h,'precipitation','precipitation_1h'),tcc:pick(d1,'totalcloudcover_total','totalcloudcover')||pick(c1h,'totalcloudcover_total','totalcloudcover'),sunmin:pick(d1,'sunshine','sunshine_time')||pick(c1h,'sunshine','sunshine_time'),blh:pick(d1,'boundarylayer_height')||pick(a1h,'boundarylayer_height'),cape:pick(d1,'cape')||pick(a1h,'cape'),cin:pick(d1,'cin')||pick(a1h,'cin'),td:pick(d1,'dewpoint_2m')||pick(a1h,'dewpoint_2m')};
}

function groupByDay(times){
  const out={};
  for(let i=0;i<times.length;i++){
    const dt=new Date(times[i]);
    const k=`${dt.getFullYear()}-${String(dt.getMonth()+1).padStart(2,'0')}-${String(dt.getDate()).padStart(2,'0')}`;
    (out[k]||=[]).push(i);
  }
  return out;
}

function thermicScore(p){
  let s=0;
  const {sun,tcc,rr,blh,cape,cin,wind10,t2m,td2m}=p;
  if(sun!=null){if(sun>=45)s+=2;else if(sun>=20)s+=1;else if(sun<=5)s-=1}
  if(tcc!=null){if(tcc<=20)s+=1;else if(tcc>=85)s-=1}
  if(rr!=null){if(rr>0)s-=(rr>=1?2:1)}
  if(blh!=null){if(blh>=1800)s+=2;else if(blh>=1200)s+=1;else if(blh<600)s-=1}
  if(cape!=null){if(cape>=50&&cape<=600)s+=1;if(cape>800)s-=1}
  if(cin!=null&&cin<-50)s-=1;
  if(wind10!=null){if(wind10>=2&&wind10<=6)s+=1;else if(wind10>9)s-=1}
  if(t2m!=null&&td2m!=null){const spread=t2m-td2m;if(spread>=6&&spread<=12)s+=1;else if(spread<3)s-=1}
  return Math.max(0,Math.min(5,Math.round(s)));
}

function climbFromPhysics(p){
  const cape=Math.max(0,p.cape||0),blh_km=Math.max(0,(p.blh||0)/1000),sunFrac=Math.max(0,Math.min(1,(p.sun||0)/60)),tccFrac=Math.max(0,Math.min(1,(p.tcc||0)/100)),rr=Math.max(0,p.precip||0),wind=Math.max(0,p.wind||0);
  let w=0.02*Math.sqrt(cape)+0.6*blh_km+0.3*sunFrac;
  w-=0.8*tccFrac;w-=0.5*Math.min(rr,2.0);w-=Math.max(0,wind-8)*0.08;
  return Math.max(0,Math.min(w,5.0));
}

function labelForScore(sc){
  if(sc<=0)return 'Thermik 0/5. Praktisch keine nutzbaren Bärte.';
  if(sc===1)return 'Thermik 1/5. Fetzen, selten zentrierbar.';
  if(sc===2)return 'Thermik 2/5. Schwach, kurzlebig.';
  if(sc===3)return 'Thermik 3/5. Brauchbar mit Arbeit.';
  if(sc===4)return 'Thermik 4/5. Gut, teils kräftig.';
  return 'Thermik 5/5. Sehr gut.';
}

function buildClimbBoxHTML(idxs,series){
  const hours=idxs.map(i=>({i,h:new Date(series.time[i]).getHours()})).filter(x=>x.h>=7&&x.h<=19);
  const uniqueHours=[...new Set(hours.map(x=>x.h))].sort((a,b)=>a-b);
  const climbData=uniqueHours.map(h=>{
    const idx=hours.find(x=>x.h===h)?.i;
    if(idx==null)return{h,climb:0};
    const sun=series.sunmin?.[idx]||0,tcc=series.tcc?.[idx]||0,rr=series.precip?.[idx]||0,blh=series.blh?.[idx]||0,cape=series.cape?.[idx]||0,wind10=series.wind10?.[idx]||0;
    const climb=climbFromPhysics({sun,tcc,precip:rr,blh,cape,wind:wind10});
    return{h,climb};
  });
  const maxClimb=Math.max(2.5,...climbData.map(x=>x.climb));
  const rows=climbData.map(d=>{
    const barWidth=Math.round((d.climb/maxClimb)*180);
    return`<tr><td style="padding:3px 8px;font-size:10px;font-weight:600;color:${palette.textSecondary};text-align:right;width:35px">${String(d.h).padStart(2,'0')}h</td><td style="padding:3px 4px"><div style="width:${barWidth}px;max-width:180px;height:10px;background:#66bb6a;border:1px solid ${palette.border};border-radius:4px"></div></td><td style="padding:3px 8px;font-size:10px;color:${palette.textSecondary}">${round(d.climb,1)} m/s</td></tr>`;
  }).join('');
  return`<div style="background:#1a2332;border:1px solid ${palette.border};border-radius:10px;padding:12px;margin-top:10px"><div style="font-size:13px;font-weight:600;margin-bottom:8px;color:${palette.textPrimary}">📊 Steigwerte (CAPE/BLH)</div><table role="presentation" style="width:100%;border-collapse:collapse">${rows}</table></div>`;
}

function buildPhaseBlocks(idxs,series){
  const phases=[{key:'morning',label:'Vormittag (08–12 Uhr)',icon:'☀️',from:8,to:12},{key:'early',label:'Früher Nachmittag (12–15 Uhr)',icon:'🌤️',from:12,to:15},{key:'late',label:'Später Nachmittag (15–18 Uhr)',icon:'⛅',from:15,to:18},{key:'eve',label:'Abends (nach 18 Uhr)',icon:'🌙',from:18,to:21}];
  const blocks=[];
  for(const phase of phases){
    const pickIdx=idxs.filter(i=>{const h=new Date(series.time[i]).getHours();return h>=phase.from&&h<phase.to});
    if(!pickIdx.length)continue;
    const avgField=(field)=>{if(!field)return null;return mean(pickIdx.map(i=>field[i]).filter(Number.isFinite))};
    const t2m=avgField(series.temp),rh=avgField(series.rh),td2m=series.td?avgField(series.td):estimateTd(t2m,rh),tcc=avgField(series.tcc),rr=avgField(series.precip)??0,blh=avgField(series.blh),cape=avgField(series.cape),cin=avgField(series.cin),wind10=avgField(series.wind10),winddir=avgField(series.winddir),sun=avgField(series.sunmin);
    const score=thermicScore({sun,tcc,rr,blh,cape,cin,wind10,t2m,td2m});
    const windStr=wind10!=null?`🌬️ Wind: ~${round(wind10)} m/s aus ${degToCompass(winddir)}`:'🌬️ Wind: —';
    const lines=[];
    if(phase.key==='morning'){
      lines.push(`• Bewölkung ${pct(tcc)} %, Schauer ${round(rr)} mm/h, BLH ~${round((blh||0)/1000)} km`);
      lines.push(`• ${windStr}`);
      lines.push(`• ${labelForScore(score)}`);
    }else if(phase.key==='early'){
      lines.push(`• Bewölkung ${pct(tcc)} %, ggf. Schauerpeak, BLH bis ~${round((blh||0)/1000)} km`);
      lines.push(`• ${windStr}`);
      lines.push(`• CAPE ~${Math.round(cape||0)} J/kg`);
      lines.push(`• ${labelForScore(score)}`);
    }else if(phase.key==='late'){
      lines.push(`• Schauertrend ↓, TCC ~${pct(tcc)} %, BLH ~${round((blh||0)/1000)} km`);
      lines.push(`• ${windStr}`);
      lines.push(`• Bestes Tagesfenster → ${labelForScore(score)}`);
    }else{
      const adjusted=Math.max(0,score-1);
      lines.push(`• Einstrahlung ↓, BLH fällt`);
      lines.push(`• ${windStr}`);
      lines.push(`• ${labelForScore(adjusted)} Ende`);
    }
    blocks.push({icon:phase.icon,title:phase.label,lines,score,wind:windStr});
  }
  return blocks;
}

function buildPhaseHTML(blocks,maxLinesGlobal){
  return blocks.map(block=>{
    const paddedLines=[...block.lines];
    while(paddedLines.length<maxLinesGlobal){
      paddedLines.push('&nbsp;');
    }
    return`<div style="background:#1a2332;border:1px solid ${palette.border};border-radius:10px;padding:12px;margin-top:10px"><div style="font-size:14px;font-weight:600;color:${palette.textPrimary};margin-bottom:6px">${block.icon} ${block.title}</div>${paddedLines.map(line=>`<div style="font-size:12px;color:${palette.textSecondary};line-height:1.6;margin:2px 0">${line}</div>`).join('')}</div>`;
  }).join('');
}

const series=parseSeries(data);
const daysMap=groupByDay(series.time);
const dayKeys=Object.keys(daysMap).sort().slice(0,3);
if(!dayKeys.length)throw new Error('Keine Tagesfenster');

const dateFormatter=new Intl.DateTimeFormat('de-DE',{weekday:'long',day:'2-digit',month:'2-digit',timeZone:'Europe/Berlin'});
const days=dayKeys.map(key=>{
  const idxs=daysMap[key];
  const dateMid=new Date(key+'T12:00:00Z');
  const title=dateFormatter.format(dateMid);
  const dayIdx=idxs.filter(i=>{const h=new Date(series.time[i]).getHours();return h>=7&&h<=19});
  const maxScore=dayIdx.length?Math.max(...dayIdx.map(i=>{
    const t2m=series.temp?.[i],rh=series.rh?.[i],td2m=series.td?.[i]??estimateTd(t2m,rh);
    return thermicScore({sun:series.sunmin?.[i],tcc:series.tcc?.[i],rr:series.precip?.[i]||0,blh:series.blh?.[i],cape:series.cape?.[i],cin:series.cin?.[i],wind10:series.wind10?.[i],t2m,td2m});
  })):0;
  const phases=buildPhaseBlocks(idxs,series);
  const climbHTML=buildClimbBoxHTML(idxs,series);
  const totalLines=phases.reduce((sum,p)=>sum+p.lines.length,0);
  return {key,title,maxScore,idxs,phases,climbHTML,phaseCount:phases.length,totalLines};
});
const maxLinesPerPhaseGlobal=Math.max(...days.flatMap(d=>d.phases.map(p=>p.lines.length)));

const firstDate=dateFormatter.format(new Date(dayKeys[0]+'T12:00:00Z'));
const lastDate=dateFormatter.format(new Date(dayKeys[dayKeys.length-1]+'T12:00:00Z'));
const subject=`🌤️ Thermik EDXE (${firstDate} – ${lastDate})`;

const html=`<!DOCTYPE html>
<html><head><meta charset="utf-8"><title>${subject}</title></head>
<body style="margin:0;padding:0;background:${palette.bg};color:${palette.textPrimary};font-family:Arial,sans-serif">
<table role="presentation" style="width:100%;border-collapse:collapse;background:${palette.bg}">
<tr><td align="center" style="padding:0">
<table role="presentation" style="max-width:1100px;width:100%;border-collapse:collapse">
<tr><td style="background:linear-gradient(135deg,${palette.teal} 0%,${palette.blue} 100%);border-radius:16px 16px 0 0;padding:24px;text-align:center">
<h1 style="font-size:38px;color:#fff;margin:0;text-shadow:0 3px 10px rgba(0,0,0,0.4)">🌤️ Thermik-Vorhersage EDXE</h1>
<p style="font-size:17px;color:#fff;opacity:0.9;margin:8px 0 0">${firstDate} – ${lastDate}</p>
<div style="display:inline-block;background:rgba(255,255,255,0.2);padding:6px 16px;border-radius:20px;margin-top:12px;font-size:14px;color:#fff">3 Tage | ⚡ Live-Daten</div>
</td></tr>
<tr><td style="padding:20px 10px"><table role="presentation" style="width:100%;border-collapse:collapse">
<tr>${days.map(day=>`<td style="width:33.33%;padding:8px;vertical-align:top;height:100%">
<table style="width:100%;height:100%;border-collapse:collapse;background:linear-gradient(135deg,${palette.cardBg} 0%,${palette.bg} 100%);border:2px solid ${palette.border};border-radius:16px;box-shadow:0 6px 20px rgba(0,0,0,0.5)">
<tr><td style="padding:16px;vertical-align:top">
<h3 style="font-size:20px;color:${palette.textPrimary};margin:0 0 12px;text-align:center">${day.title}</h3>
<div style="background:${scoreColors[day.maxScore].grad};color:#fff;padding:16px;border-radius:12px;text-align:center;box-shadow:0 6px 16px rgba(0,0,0,0.6);border:2px solid #fff;margin-bottom:16px">
<div style="font-size:42px;font-weight:bold;text-shadow:0 2px 4px rgba(0,0,0,0.3)">${day.maxScore}<span style="font-size:24px;opacity:0.8">/5</span></div>
<div style="font-size:16px;margin-top:6px">${scoreColors[day.maxScore].emoji} ${scoreColors[day.maxScore].label}</div>
</div>
${day.climbHTML}
${buildPhaseHTML(day.phases,maxLinesPerPhaseGlobal)}
</td></tr></table>
</td>`).join('')}</tr>
</table></td></tr>
<tr><td style="text-align:center;padding:20px;border-top:1px solid ${palette.border}">
<p style="font-size:13px;color:${palette.textTertiary};margin:0">📊 Datenquelle: <a href="https://meteoblue.com" style="color:${palette.teal};text-decoration:none">Meteoblue API</a><br>
<span style="font-size:11px;opacity:0.7">🤖 Automatisch generiert um 07:00 Uhr</span></p>
</td></tr>
</table></td></tr></table>
</body></html>`;

function buildClimbTextTelegram(idxs,series){
  const hours=idxs.map(i=>({i,h:new Date(series.time[i]).getHours()})).filter(x=>x.h>=7&&x.h<=19);
  const uniqueHours=[...new Set(hours.map(x=>x.h))].sort((a,b)=>a-b);
  const climbData=uniqueHours.map(h=>{
    const idx=hours.find(x=>x.h===h)?.i;
    if(idx==null)return null;
    const sun=series.sunmin?.[idx]||0,tcc=series.tcc?.[idx]||0,rr=series.precip?.[idx]||0,blh=series.blh?.[idx]||0,cape=series.cape?.[idx]||0,wind10=series.wind10?.[idx]||0;
    const climb=climbFromPhysics({sun,tcc,precip:rr,blh,cape,wind:wind10});
    return{h,climb};
  }).filter(Boolean);
  const peaks=climbData.filter(d=>d.climb>=1.5).slice(0,3);
  if(peaks.length===0)return'📊 Steigwerte: schwach (unter 1.5 m/s)';
  return`📊 Steigwerte: ${peaks.map(p=>`${String(p.h).padStart(2,'0')}h=${round(p.climb,1)}m/s`).join(', ')}`;
}

const telegramText=`🌤️ <b>Thermik EDXE | ${firstDate.split(',')[1].trim()} – ${lastDate.split(',')[1].trim()}</b>\n\n${days.map(day=>`<b>${scoreColors[day.maxScore].emoji} ${day.title}</b>\nScore: <code>${day.maxScore}/5</code> – ${scoreColors[day.maxScore].label}\n${buildClimbTextTelegram(day.idxs,series)}\n\n${day.phases.map(p=>`${p.icon} <b>${p.title}</b>\n${p.lines.join('\n')}\n`).join('\n')}\n`).join('\n')}🤖 <i>Meteoblue API | Generiert 07:00</i>`;

return [{json:{subject,html,telegram_chat_id:'5716776863',telegram_text:telegramText,telegram_parse_mode:'HTML'}}];
